import tailwindcss from "@tailwindcss/vite";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [tailwindcss()],
});

@media (hover: hover) {
  :is(:where(.group):hover .group-hover\:text-blue-700) {
    color: var(--color-blue-700);
  }
}
:is(:where(.peer):user-invalid ~ .peer-user-invalid\:block) {
  display: block;
}
.user-invalid\:border-red-600:user-invalid {
  border-color: var(--color-red-600);
}
@media (hover: hover) {
  .hover\:border-blue-600:hover {
    border-color: var(--color-blue-600);
  }
}
.focus-visible\:outline-2:focus-visible {
  outline-style: var(--tw-outline-style);
  outline-width: 2px;
}
.focus-visible\:outline-blue-600:focus-visible {
  outline-color: var(--color-blue-600);
}
.disabled\:opacity-50:disabled {
  opacity: 50%;
}
.aria-expanded\:bg-gray-100[aria-expanded="true"] {
  background-color: var(--color-gray-100);
}

@media (width < 40rem) {
  .max-sm\:hidden {
    display: none;
  }
}
@media (width >= 48rem) {
  .md\:grid-cols-2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (width >= 64rem) {
  .lg\:grid-cols-3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@container (width >= 28rem) {
  .\@md\:w-40 {
    width: calc(var(--spacing) * 40);
  }
  .\@md\:flex-row {
    flex-direction: row;
  }
  .\@md\:items-center {
    align-items: center;
  }
}
.dark\:border-gray-800:where([data-theme="dark"], [data-theme="dark"] *) {
  border-color: var(--color-gray-800);
}
.dark\:text-gray-400:where([data-theme="dark"], [data-theme="dark"] *) {
  color: var(--color-gray-400);
}

@import "tailwindcss";

@theme {
  --color-brand-50: oklch(0.97 0.02 160);
  --color-brand-600: oklch(0.52 0.12 160);
  --color-brand-700: oklch(0.45 0.11 160);
  --font-display: "Fraunces", Georgia, serif;
  --radius-card: 1rem;
  --breakpoint-3xl: 120rem;
}

@utility content-auto {
  content-visibility: auto;
}

@layer components {
  .trail-note {
    border-radius: var(--radius-card);
    background: var(--color-brand-50);

    @variant dark {
      background: var(--color-brand-700);
    }
  }
}

@layer theme {
  :root, :host {
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue",
      "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji",
      "Segoe UI Symbol", "Noto Color Emoji";
    --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --color-white: #fff;
    --spacing: 0.25rem;
    --text-4xl: 2.25rem;
    --text-4xl--line-height: calc(2.5 / 2.25);
    --default-font-family: var(--font-sans);
    --default-mono-font-family: var(--font-mono);
    --color-brand-50: oklch(0.97 0.02 160);
    --color-brand-600: oklch(0.52 0.12 160);
    --color-brand-700: oklch(0.45 0.11 160);
    --font-display: "Fraunces", Georgia, serif;
    --radius-card: 1rem;
  }
}
@layer components {
  .trail-note {
    border-radius: var(--radius-card);
    background: var(--color-brand-50);
    @media (prefers-color-scheme: dark) {
      background: var(--color-brand-700);
    }
  }
}
@layer utilities {
  .rounded-card {
    border-radius: var(--radius-card);
  }
  .bg-brand-600 {
    background-color: var(--color-brand-600);
  }
  .p-4 {
    padding: calc(var(--spacing) * 4);
  }
  .p-6 {
    padding: calc(var(--spacing) * 6);
  }
  .font-display {
    font-family: var(--font-display);
  }
  .text-4xl {
    font-size: var(--text-4xl);
    line-height: var(--tw-leading, var(--text-4xl--line-height));
  }
  .text-white {
    color: var(--color-white);
  }
  .content-auto {
    content-visibility: auto;
  }
  @media (width >= 120rem) {
    .\33 xl\:p-10 {
      padding: calc(var(--spacing) * 10);
    }
  }
}

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

const base = "rounded-lg px-4 py-2 font-semibold";
const isActive = true;
const isDisabled = false;

console.log(clsx(base, isActive && "bg-blue-600 text-white", isDisabled && "opacity-50"));
console.log(`${base} px-2`);
console.log(twMerge(base, "px-2"));
console.log(cn(base, "bg-blue-600 hover:bg-blue-700", isActive && "bg-green-600"));
